package vn.edu.eaut.lab9.repository; import jakarta.persistence.*;import vn.edu.eaut.lab9.config.JPAUtil;import vn.edu.eaut.lab9.model.*;import java.util.*; public class LopHocRepository extends BaseRepository<LopHoc,Integer>{protected Class<LopHoc> type(){return LopHoc.class;} public List<LopHoc> findAll(){EntityManager e=JPAUtil.getEntityManagerFactory().createEntityManager();try{return e.createQuery("select distinct l from LopHoc l left join fetch l.sinhViens order by l.id",LopHoc.class).getResultList();}finally{e.close();}}}